package cn.nemo.qingxiao;
import android.app.*;
import android.content.*;
import android.os.Build;
import org.json.*;
import java.util.UUID;

public class TimerEngine {
 static JSONObject get(Context c)throws Exception {String s=c.getSharedPreferences("timer",0).getString("active",null);return s==null?null:new JSONObject(s);}
 static void put(Context c,JSONObject t){android.content.SharedPreferences.Editor e=c.getSharedPreferences("timer",0).edit();if(t==null)e.remove("active");else e.putString("active",t.toString());e.commit();}
 static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,0,new Intent(c,TimerReceiver.class).addFlags(Intent.FLAG_RECEIVER_FOREGROUND).setAction("expire"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,JSONObject t){AlarmManager m=c.getSystemService(AlarmManager.class);m.cancel(alarm(c));if(t==null||!"running".equals(t.optString("state")))return;long at=t.optLong("endAt");if(Build.VERSION.SDK_INT<31||m.canScheduleExactAlarms())m.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c));else m.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,alarm(c));}
 static void pause(JSONObject t,long now)throws Exception {if(!"running".equals(t.optString("state")))return;long end=Math.min(now,t.getLong("endAt")),start=t.getLong("segmentStartedAt");if(end>start)t.getJSONArray("segments").put(new JSONObject().put("startAt",start).put("endAt",end));t.put("remainingMs",Math.max(0,t.getLong("endAt")-now));t.put("state","paused");}
 static void finish(Context c,JSONObject t,long now,boolean notify)throws Exception {
  boolean full=("running".equals(t.optString("state"))&&now>=t.getLong("endAt"))||("paused".equals(t.optString("state"))&&t.optLong("remainingMs")==0);pause(t,now);JSONArray seg=t.getJSONArray("segments");long duration=0,end=now;for(int i=0;i<seg.length();i++){JSONObject p=seg.getJSONObject(i);duration+=p.getLong("endAt")-p.getLong("startAt");end=p.getLong("endAt");}
  JSONObject db=new JSONObject(Store.read(c));JSONArray sessions=db.optJSONArray("sessions");if(sessions==null){sessions=new JSONArray();db.put("sessions",sessions);}String id="session:"+t.getString("id");boolean exists=false;for(int i=0;i<sessions.length();i++)if(id.equals(sessions.getJSONObject(i).optString("id")))exists=true;
  if(!exists&&duration>0){JSONObject s=new JSONObject();for(String k:new String[]{"title","taskId","subtaskId","project","category","deviceId","mode","plannedMs"})s.put(k,t.opt(k));s.put("id",id).put("status",full?"completed":"partial").put("startAt",t.getLong("startedAt")).put("endAt",end).put("durationMs",duration).put("segments",seg).put("deleted",false).put("updatedAt",now).put("_dirty",true).put("_op",UUID.randomUUID().toString()).put("_rev",0);sessions.put(s);Store.write(c,db.toString());}
  put(c,null);schedule(c,null);NotificationManager nm=c.getSystemService(NotificationManager.class);nm.cancel(200);
  if(notify){nm.createNotificationChannel(new NotificationChannel("focus_done","番茄完成提醒",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(c,200,new Intent(c,MainActivity.class).putExtra("focus",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(201,new Notification.Builder(c,"focus_done").setSmallIcon(R.drawable.ic_notification).setContentTitle("focus".equals(t.optString("mode"))?"番茄完成，休息一下吧":"休息结束").setContentText(t.optString("title")+" · 已保存时间记录").setContentIntent(open).setAutoCancel(true).build());}
 }
 static void ongoing(Context c,JSONObject t){if(t==null)return;NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("focus_active","进行中的番茄",NotificationManager.IMPORTANCE_LOW));boolean running="running".equals(t.optString("state"));PendingIntent open=PendingIntent.getActivity(c,200,new Intent(c,MainActivity.class).putExtra("focus",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String action=running?"pause":"resume";PendingIntent control=PendingIntent.getBroadcast(c,201,new Intent(c,TimerReceiver.class).addFlags(Intent.FLAG_RECEIVER_FOREGROUND).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,"focus_active").setSmallIcon(R.drawable.ic_notification).setContentTitle((running?"专注中 · ":"已暂停 · ")+t.optString("title")).setContentText(running?"到时自动记录；可打开查看或暂停":"暂停期间不计入专注").setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(null,running?"暂停":"继续",control).build());if(running)b.setWhen(t.optLong("endAt")).setUsesChronometer(true).setChronometerCountDown(true);nm.notify(200,b.build());}
 public static JSONObject state(Context c)throws Exception {synchronized(Store.class){JSONObject t=get(c);if(t!=null&&"running".equals(t.optString("state"))&&System.currentTimeMillis()>=t.optLong("endAt")){finish(c,t,System.currentTimeMillis(),true);t=null;}return new JSONObject().put("timer",t==null?JSONObject.NULL:t);}}
 public static JSONObject action(Context c,String action,JSONObject input)throws Exception {synchronized(Store.class){state(c);JSONObject t=get(c);long now=System.currentTimeMillis();if("start".equals(action)){if(t!=null)throw new Exception("已有进行中的番茄");int minutes=input.optInt("minutes");if(minutes<1||minutes>180)throw new Exception("时长须为1～180分钟");long ms=minutes*60000L;t=new JSONObject();for(String k:new String[]{"title","taskId","subtaskId","project","category","deviceId"})t.put(k,input.optString(k));t.put("id",UUID.randomUUID().toString()).put("mode",input.optString("mode","focus")).put("state","running").put("plannedMs",ms).put("remainingMs",ms).put("startedAt",now).put("segmentStartedAt",now).put("endAt",now+ms).put("segments",new JSONArray());}
  else if(t!=null){if("pause".equals(action))pause(t,now);else if("resume".equals(action)&&"paused".equals(t.optString("state")))t.put("state","running").put("segmentStartedAt",now).put("endAt",now+t.getLong("remainingMs"));else if("finish".equals(action)){finish(c,t,now,false);t=null;}}
  put(c,t);schedule(c,t);ongoing(c,t);return new JSONObject().put("timer",t==null?JSONObject.NULL:t);
 }}
 public static void restore(Context c){try{synchronized(Store.class){state(c);JSONObject t=get(c);schedule(c,t);ongoing(c,t);}}catch(Exception e){android.util.Log.e("Qingxiao","Timer restore failed");}}
}
